head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[audio > P > preload]<br/>Audio 컴포넌트의 오디오 데이터 버퍼링 방식을 설정합니다.",
    "validation" : [
        "auto 설정 시, 오디오 데이터 전체를 미리 내려받도록 브라우저에 요청합니다.",
        "빈 문자열('') 을 설정 시 'auto' 로 동작합니다.",
        "metadata 설정 시, 오디오의 메타 데이터만 미리 내려받도록 브라우저에 요청합니다.",
        "none 설정 시, 재생을 시작하기 전에는 오디오 데이터를 내려받지 않도록 브라우저에 요청합니다.",
        "Audio 컴포넌트는 preload 속성값을 출력 HTML 의 audio 태그에 전달하며, 실제 동작은 브라우저의 HTML5 audio 처리에 따라 결정됩니다.",
        "속성을 한번이라도 설정하면 속성명이 유지되고, 속성명 정의만으로 해당 기능이 설정됩니다.",
        "따라서, 소스에서 직접 속성명을 제거해야 해당 기능이 해제됩니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 재생 시작 전 버퍼링 상태 확인
scwin.btn_getBufferState_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");
    let el4 = document.querySelector("#target4");

    let getState = function (el) {
        return "정규화값(preload) : " + el.preload + " , 데이터 준비 상태(readyState) : " + el.readyState + " , 내려받기 상태(networkState) : " + el.networkState + " , 내려받은 구간 수(buffered.length) : " + el.buffered.length;
    };

    wf_body_bottom.getObj("scwin").setReturnValue("preload 를 auto 로 설정 - " + getState(el1));
    wf_body_bottom.getObj("scwin").setReturnValue("preload 를 빈 문자열로 설정 - " + getState(el2));
    wf_body_bottom.getObj("scwin").setReturnValue("preload 를 metadata 로 설정 - " + getState(el3));
    wf_body_bottom.getObj("scwin").setReturnValue("preload 를 none 으로 설정 - 재생 시작 전 " + getState(el4));
};



// 출력 HTML audio 태그로 전달된 preload 속성값과 속성명 정의만으로의 설정 상태 확인
scwin.btn_getPreloadAttr_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");
    let el4 = document.querySelector("#target4");
    let el5 = document.querySelector("#target5");

    wf_body_bottom.getObj("scwin").setReturnValue("출력 HTML audio 태그의 preload 속성값 - target1 : " + JSON.stringify(el1.getAttribute("preload")) + " , target2 : " + JSON.stringify(el2.getAttribute("preload")) + " , target3 : " + JSON.stringify(el3.getAttribute("preload")) + " , target4 : " + JSON.stringify(el4.getAttribute("preload")));
    wf_body_bottom.getObj("scwin").setReturnValue("속성명 유지 및 속성명 정의만으로 기능 설정 - 속성명만 정의한 target2 의 속성 보유 여부 : " + el2.hasAttribute("preload") + " , 정규화값(preload) : " + el2.preload + " , 값을 명시한 target1 의 정규화값(preload) : " + el1.preload);
    wf_body_bottom.getObj("scwin").setReturnValue("소스에서 preload 속성명 제거 시 해제 - target5 의 속성 보유 여부 : " + el5.hasAttribute("preload") + " , 속성값 : " + JSON.stringify(el5.getAttribute("preload")) + " , 정규화값(preload) : " + el5.preload);
};
